161	/**
162	 * A period of the sheet: a name unique on the sheet, from and to a date, both inclusive. Once
163	 * closed, its due-total and each person's due-total for it are fixed at what they were when it was
164	 * closed; reopened, they are live again. Soft-closed, its figures are fixed the same way, but claims
165	 * due inside it can still change.
166	 */
167	@Entity
168	@Table(name = "period")
169	public class Period {
170	
171	    @Id
172	    @GeneratedValue(strategy = GenerationType.IDENTITY)
173	    private Long id;
174	
175	    @Column(name = "sheet_id", nullable = false)
176	    private String sheetId;
177	
178	    @Column(name = "name", nullable = false)
179	    private String name;
180	
181	    @Column(name = "from_date", nullable = false)
182	    private LocalDate fromDate;
183	
184	    @Column(name = "to_date", nullable = false)
185	    private LocalDate toDate;
186	
187	    @Column(name = "closed", nullable = false)
188	    private boolean closed;
189	
190	    /** Whether it is soft-closed: its figures fixed, its claims still free to change. Never with closed. */
191	    @Column(name = "soft_closed", nullable = false)
192	    private boolean softClosed;
193	
194	    /** The due-total fixed when the period was closed or soft-closed; none while it is open. */
195	    @Column(name = "closed_due_total", precision = 14, scale = 2)
196	    private BigDecimal closedDueTotal;
197	
198	    /** Each person's due-total for it fixed when it was closed, by person id; empty while it is open. */
199	    @ElementCollection(fetch = FetchType.EAGER)
200	    @CollectionTable(name = "period_person_due", joinColumns = @JoinColumn(name = "period_id"))
201	    @MapKeyColumn(name = "person_id")
202	    @Column(name = "due_total", nullable = false, precision = 14, scale = 2)
203	    private Map<Long, BigDecimal> closedPersonDues = new TreeMap<>();
204	
205	    protected Period() {}
206	
207	    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
208	        this.sheetId = sheetId;
209	        this.name = name;
210	        this.fromDate = fromDate;
211	        this.toDate = toDate;
212	    }
213	
214	    public Long getId() { return id; }
215	
216	    public String getSheetId() { return sheetId; }
217	
218	    public String getName() { return name; }
219	
220	    public LocalDate getFromDate() { return fromDate; }
221	
222	    public LocalDate getToDate() { return toDate; }
223	
224	    public boolean isClosed() { return closed; }
225	
226	    public boolean isSoftClosed() { return softClosed; }
227	
228	    public BigDecimal getClosedDueTotal() { return closedDueTotal; }
229	
230	    public Map<Long, BigDecimal> getClosedPersonDues() { return closedPersonDues; }
231	
232	    /** Close it, fixing each person's due-total for it and its own, the sum of theirs. */
233	    public void close(Map<Long, BigDecimal> personDues) {
234	        fix(personDues);
235	        this.closed = true;
236	        this.softClosed = false;
237	    }
238	
239	    /** Soft-close it, fixing its figures as a close does while its claims can still change. */
240	    public void softClose(Map<Long, BigDecimal> personDues) {
241	        fix(personDues);
242	        this.softClosed = true;
243	    }
244	
245	    private void fix(Map<Long, BigDecimal> personDues) {
246	        this.closedPersonDues.clear();
247	        this.closedPersonDues.putAll(personDues);
248	        this.closedDueTotal = personDues.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
249	    }
250	
251	    /** Reopen it: its due-total is live again. */
252	    public void reopen() {
253	        this.closed = false;
254	        this.softClosed = false;
255	        this.closedDueTotal = null;
256	        this.closedPersonDues.clear();
257	    }
258	
259	    /** Whether the date falls in it, both ends inclusive. */
260	    public boolean contains(LocalDate date) {
261	        return !date.isBefore(fromDate) && !date.isAfter(toDate);
262	    }
263	
264	    /** Whether it shares a date with the other dates, both inclusive. */
265	    public boolean overlaps(LocalDate from, LocalDate to) {
266	        return !fromDate.isAfter(to) && !from.isAfter(toDate);
267	    }
268	}
