338	import java.util.stream.Collectors;
339	import net.officefloor.hq.app.Audit;
340	import net.officefloor.hq.app.claim.Claim;
341	import net.officefloor.hq.app.claim.ClaimRepository;
342	import net.officefloor.hq.app.claim.ClaimService;
343	import net.officefloor.hq.app.person.Person;
344	import net.officefloor.hq.app.person.PersonRepository;
345	import net.officefloor.hq.app.setting.SettingService;
346	import net.officefloor.hq.app.sheet.SheetNotFoundException;
347	import net.officefloor.hq.app.sheet.SheetRepository;
348	import org.springframework.stereotype.Service;
349	import org.springframework.transaction.annotation.Transactional;
350	
351	/**
352	 * The sheet's periods: each named uniquely on the sheet, from and to a date inclusive, none
353	 * overlapping. Closing a period fixes, at that moment, each person's due-total for it (the figures
354	 * as shown then of their claims whose due-by falls in it that counted by the status they had at the
355	 * end of its last day) and its own due-total, the sum of theirs. Soft-closing fixes them the same
356	 * way while claims due inside it can still change; a soft-closed period can then be closed (fixing
357	 * them afresh). A steward can reopen a closed or soft-closed period, making its due-total live again.
358	 */
359	@Service
360	public class PeriodService {
361	
362	    private final PeriodRepository periods;
363	    private final SheetRepository sheets;
364	    private final ClaimRepository claims;
365	    private final PersonRepository people;
366	    private final ClaimService claimService;
367	    private final SettingService settings;
368	    private final Audit audit;
369	
370	    public PeriodService(PeriodRepository periods, SheetRepository sheets, ClaimRepository claims,
371	            PersonRepository people, ClaimService claimService, SettingService settings, Audit audit) {
372	        this.settings = settings;
373	        this.periods = periods;
374	        this.sheets = sheets;
375	        this.claims = claims;
376	        this.people = people;
377	        this.claimService = claimService;
378	        this.audit = audit;
379	    }
380	
381	    @Transactional(readOnly = true)
382	    public List<Period> list(String sheetId) {
383	        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
384	    }
385	
386	    @Transactional
387	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
388	        if (to.isBefore(from)) throw new PeriodDatesException();
389	        // Lock the sheet so two users adding periods at once cannot overlap or share a name.
390	        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
391	        if (periods.existsBySheetIdAndName(sheetId, name)) throw new DuplicatePeriodNameException();
392	        if (periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
393	            throw new PeriodOverlapException();
394	        }
395	        Period saved = periods.saveAndFlush(new Period(sheetId, name, from, to));
396	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user.strip()
397	                + " period=" + saved.getName() + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
398	        return saved;
399	    }
400	
401	    /**
402	     * Make one period per calendar month from the from-date's month to the to-date's month, each from
403	     * the first to the last day of its month and named yyyy-mm. A month whose name is already a period,
404	     * or whose days overlap one on the sheet, is left out; the others are still made. A blank date
405	     * takes the sheet's today.
406	     */
407	    @Transactional
408	    public List<Period> generate(String sheetId, String user, LocalDate fromOrNull, LocalDate toOrNull) {
409	        // Lock the sheet so two users adding periods at once cannot overlap or share a name.
410	        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
411	        LocalDate from = fromOrNull == null ? today : fromOrNull;
412	        LocalDate to = toOrNull == null ? today : toOrNull;
413	        if (to.isBefore(from)) throw new PeriodDatesException();
414	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
415	        List<Period> made = new ArrayList<>();
416	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
417	            String name = month.toString();
418	            LocalDate first = month.atDay(1);
419	            LocalDate last = month.atEndOfMonth();
420	            if (existing.stream().anyMatch(p -> p.getName().equals(name) || p.overlaps(first, last))) continue;
421	            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
422	            existing.add(saved);
423	            made.add(saved);
424	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user.strip()
425	                    + " period=" + saved.getName() + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
426	        }
427	        return made;
428	    }
429	
430	    /**
431	     * Make the twelve monthly periods of the fiscal year named FY&lt;year&gt;, the one whose first day (the
432	     * first of the sheet's fiscal start month) falls in that calendar year, exactly as {@link #generate} does.
433	     */
434	    @Transactional
435	    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
436	        YearMonth first = YearMonth.of(year, settings.fiscalStartMonth(sheetId));
437	        return generate(sheetId, user, first.atDay(1), first.plusMonths(11).atEndOfMonth());
438	    }
439	
440	    @Transactional
441	    public Period close(String sheetId, String user, Long id) {
442	        // Lock the sheet so no claim in the period changes while its due-total is fixed.
443	        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
444	        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
445	        if (!settings.mayDo(sheetId, user, "close")) throw new PeriodNotPermittedException();
446	        if (period.isClosed()) throw new PeriodClosedException();
447	        return fix(sheetId, user, period, today, false, false);
448	    }
449	
450	    @Transactional
451	    public Period softClose(String sheetId, String user, Long id) {
452	        // Lock the sheet so no claim in the period changes while its due-total is fixed.
453	        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
454	        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
455	        if (!settings.mayDo(sheetId, user, "close")) throw new PeriodNotPermittedException();
456	        if (period.isClosed() || period.isSoftClosed()) throw new PeriodClosedException();
457	        return fix(sheetId, user, period, today, false, true);
458	    }
459	
460	    /**
461	     * Close, as a close by hand would, every open period (not a soft-closed one) whose to-date plus the grace days is before the
462	     * sheet's today, in order of their to-dates, each audited with auto=yes. The caller holds the sheet's
463	     * lock, with its new today already set.
464	     */
465	    @Transactional
466	    public void autoClose(String sheetId, String user, LocalDate today, int graceDays) {
467	        List<Period> due = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
468	                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getToDate().plusDays(graceDays).isBefore(today))
469	                .sorted(Comparator.comparing(Period::getToDate))
470	                .toList();
471	        for (Period period : due) fix(sheetId, user, period, today, true, false);
472	    }
473	
474	    /** Close or soft-close the period, fixing each person's due-total for it and its own, and audit it. */
475	    private Period fix(String sheetId, String user, Period period, LocalDate today, boolean auto, boolean soft) {
476	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
477	                .collect(Collectors.toMap(Person::getId, Function.identity()));
478	        // Every person on the sheet gets a figure, 0.00 when none of their claims falls in it.
479	        Map<Long, BigDecimal> personDues = new LinkedHashMap<>();
480	        for (Long personId : byId.keySet()) personDues.put(personId, BigDecimal.ZERO.setScale(2));
481	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
482	            Person person = byId.get(claim.getPersonId());
483	            if (person == null || !period.contains(claim.getDueBy()) || !person.countsAt(claim, period.getToDate(), today)) continue;
484	            BigDecimal figure = claimService.chargedFigureOf(sheetId, person, claim);
485	            if (figure != null) personDues.merge(person.getId(), figure, BigDecimal::add);
486	        }
487	        if (soft) period.softClose(personDues);
488	        else period.close(personDues);
489	        Period saved = periods.saveAndFlush(period);
490	        audit.recordOnCommit((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + user.strip()
491	                + " period=" + saved.getName() + " total=" + saved.getClosedDueTotal().setScale(2).toPlainString()
492	                + (auto ? " auto=yes" : ""));
493	        return saved;
494	    }
495	
496	    @Transactional
497	    public Period reopen(String sheetId, String user, Long id) {
498	        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
499	        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
500	        if (!settings.mayDo(sheetId, user, "reopen")) throw new PeriodNotPermittedException();
501	        if (!period.isClosed() && !period.isSoftClosed()) throw new PeriodOpenException();
502	        period.reopen();
503	        Period saved = periods.saveAndFlush(period);
504	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user.strip()
505	                + " period=" + saved.getName());
506	        return saved;
507	    }
508	}
